WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_rt_ratio'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '往返比例关系', 'kp-trv-rt-ratio', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "往返比例关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目完全没有绝对的距离和时间，全程玩比例互推。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“去程速度提高了 20%，回程速度降低了 20%，问总时间变化了多少？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不要设繁琐的 X，直接赋特值。令原本的单程路程 S 为最小公倍数，原本的速度 V 为好算的值。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 一辆车原路往返。去程提速 25%，回程降速 20%。问往返总时间与原来相比怎么变化？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋初值：令原本的速度 V = 20，路程 S = 100。原单程时间 = 5，原往返总时间 = 10。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算去程：提速 25%，V去 = 20 × 1.25 = 25。去程时间 = 100 / 25 = 4。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算回程：降速 20%，V回 = 20 × 0.8 = 16。回程时间 = 100 / 16 = 6.25。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算新总时：新往返总时间 = 4 + 6.25 = 10.25。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "对比结论：10.25 / 10 = 1.025。所以总时间增加了 2.5%。"}]}]}]}]}$$ AS jsonb), NULL, '往返比例关系的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "往返比例关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_rt_ratio", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
